import { eq } from "drizzle-orm";
import { db } from "@/db";
import { videos } from "@/db/schema";
import { isMuxEnabled, muxReady, publicMuxPoster } from "@/lib/mux-stream";

export const dynamic = "force-dynamic";

// Poster frames are generated by Mux. Published posters are public so they can
// be used as social/OG images; drafts are not exposed here.
export async function GET(request: Request, { params }: { params: Promise<{ slug: string }> }) {
  if (!isMuxEnabled()) return new Response(null, { status: 404 });
  const [video] = await db.select({ playbackId: videos.muxPlaybackId, status: videos.status }).from(videos).where(eq(videos.slug, (await params).slug)).limit(1);
  if (!video?.playbackId || video.status !== "published") return new Response(null, { status: 404 });
  if (request.method === "HEAD") return new Response(null, { status: 200 });
  return Response.redirect(publicMuxPoster(video.playbackId, 2), 302);
}
